#' PERMDISP
#'
#' Tests whether groups differ in multivariate dispersion using 
#' vegan::betadisper and permutation tests. Includes distance-to-centre 
#' summaries, diagnostics, and an optional ordination.
#' @section References:
#' Oksanen et al. (2026). vegan: Community Ecology Package (R package version 2.7-5). https://vegandevs.github.io/vegan/
#'
#' Anderson, M. J. (2006). Distance-based tests for homogeneity of multivariate dispersions. Biometrics, 62(1), 245-253. https://doi.org/10.1111/j.1541-0420.2005.00440.x
#'
#' @param data .
#' @param vars .
#' @param factor .
#' @param transform .
#' @param distance .
#' @param distBinary .
#' @param distSqrt .
#' @param distAdd .
#' @param seed .
#' @param permN .
#' @param permRestriction .
#' @param permScheme .
#' @param useParallel .
#' @param dispType .
#' @param dispBias .
#' @param dispPairwise .
#' @param dispAdjust .
#' @param showDistancePlot .
#' @param showOrdinationPlot .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guidance} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$warnings} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$anova} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$pairwise} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$plotDescription} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$plot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$distances} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$ordinationDescription} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$ordinationPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$ordinationScores} \tab \tab \tab \tab \tab a table \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$anova$asDF}
#'
#' \code{as.data.frame(results$anova)}
#'
#' @export
permdisp <- function(
    data,
    vars,
    factor,
    transform = "none",
    distance = "bray",
    distBinary = FALSE,
    distSqrt = FALSE,
    distAdd = "none",
    seed = 0,
    permN = 999,
    permRestriction = "free",
    permScheme = "free",
    useParallel = FALSE,
    dispType = "median",
    dispBias = FALSE,
    dispPairwise = FALSE,
    dispAdjust = "holm",
    showDistancePlot = TRUE,
    showOrdinationPlot = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("permdisp requires jmvcore to be installed (restart may be required)")

    if ( ! missing(vars)) vars <- jmvcore::resolveQuo(jmvcore::enquo(vars))
    if ( ! missing(factor)) factor <- jmvcore::resolveQuo(jmvcore::enquo(factor))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(vars), vars, NULL),
            `if`( ! missing(factor), factor, NULL))

    for (v in factor) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- permdispOptions$new(
        vars = vars,
        factor = factor,
        transform = transform,
        distance = distance,
        distBinary = distBinary,
        distSqrt = distSqrt,
        distAdd = distAdd,
        seed = seed,
        permN = permN,
        permRestriction = permRestriction,
        permScheme = permScheme,
        useParallel = useParallel,
        dispType = dispType,
        dispBias = dispBias,
        dispPairwise = dispPairwise,
        dispAdjust = dispAdjust,
        showDistancePlot = showDistancePlot,
        showOrdinationPlot = showOrdinationPlot)

    analysis <- permdispClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

